def test_stt_final_boundary_enables_vad_without_clip_timestamps() -> None:
    kwargs = _stt_final_boundary_kwargs()

    assert kwargs["faster_whisper_vad_filter"] is True
    assert kwargs["ensure_sentence_ends_with_period"] is False
    assert "clip_timestamps" not in kwargs


def test_listener_snapshot_reports_typed_health_and_transcript_time(tmp_path) -> None:
    asyncio.run(_assert_listener_snapshot_reports_typed_health_and_transcript_time(tmp_path))


async def _assert_listener_snapshot_reports_typed_health_and_transcript_time(tmp_path) -> None:
    state = RuntimeState(
        AppSettings(skill_root=tmp_path, data_dir=tmp_path / "data", profile_path=tmp_path / "p.yaml", repo_roots=[]),
        InterviewProfile(name="listener-health"),
    )
    await state.start_session(consent_confirmed=True)
    quiet = await state.set_listener_info({"device": "bluez_input.test", "resolve_reason": "auto_jabra_input", "mode": "pipewire", "level": "0"})
    assert quiet.listener is not None
    assert quiet.listener["health"] == "quiet"
    assert quiet.listener["capture_mode"] == "pipewire"

    active = await state.set_listener_info({"device": "bluez_input.test", "resolve_reason": "auto_jabra_input", "mode": "pipewire", "level": "42"})
    assert active.listener is not None
    assert active.listener["health"] == "active"
    assert active.listener["last_audio_at"]

    with_transcript = await state.append_transcript(TranscriptEvent(
        speaker=Speaker.INTERVIEWER,
        kind=TranscriptKind.FINAL,
        text="What is the time complexity and why?",
    ))
    assert with_transcript.listener is not None
    assert with_transcript.listener["last_transcript_at"]
